-- 1. Create group roles without login
CREATE ROLE app_readonly;
CREATE ROLE app_readwrite;

-- 2. Grant table permissions to groups
GRANT SELECT ON ALL TABLES IN SCHEMA public TO app_readonly;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_readwrite;

-- 3. Configure DEFAULT PRIVILEGES for future tables
ALTER DEFAULT PRIVILEGES IN SCHEMA public 
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_readwrite;

-- 4. Create actual application login role and grant membership
CREATE ROLE nextjs_backend WITH LOGIN PASSWORD 'strong_scram_pass';
GRANT app_readwrite TO nextjs_backend;

-- The role can see objects in the schema
GRANT USAGE ON SCHEMA app TO app_rw;

-- Read and write the existing tables
GRANT SELECT, INSERT, UPDATE, DELETE
ON ALL TABLES IN SCHEMA app TO app_rw;

-- INSERT into an identity column needs sequence rights
GRANT USAGE, SELECT
ON ALL SEQUENCES IN SCHEMA app TO app_rw;

-- Apply the same grants to objects created later
ALTER DEFAULT PRIVILEGES IN SCHEMA app
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO app_rw;

ALTER DEFAULT PRIVILEGES IN SCHEMA app
GRANT USAGE, SELECT ON SEQUENCES TO app_rw;

-- Audit who has what
SELECT grantee, privilege_type
FROM information_schema.role_table_grants
WHERE table_schema = 'app'
  AND table_name   = 'orders';
